//! Golden test for `pr_app::presenters::benchmark_presentation` (W8-10h, red: the bodies are `todo!()`).
//!
//! Reads `tests/golden/benchmark-presentation.json` (generated by `oracle-cs benchmark-presentation` at baseline
//! `d92d6aae`, the C# `BenchmarkPresentation.cs` and its private `MillisecondsText`) and runs every case. Every case
//! is checked; mismatches are collected and reported together, each named by the case `name`.
//! C#: BenchmarkRowTextTests / BenchmarkTextTests / DiagnosticsUnitsLeftoversTests (golden twin, all kinds).

use pr_app::presenters::benchmark_presentation::{
    BenchmarkProfileItem, BenchmarkResultRow, RowError, describe_error, loading_mode_text, milliseconds_text,
    profile_description, profile_key, profile_name, progress_message, workload_text,
};
use pr_bench::models::{
    BenchmarkPhaseResult, BenchmarkProfile, BenchmarkProfileError, BenchmarkProfileProblem, BenchmarkResultStatus,
    BenchmarkWorkload,
};
use pr_bench::profiles;
use pr_core::model::enums::LoadingMode;
use pr_l10n::localizer::{Localizer, built_in_english_localizer};
use pr_test_support::golden::{i64_of, load, str_of};
use serde_json::Value;

/// A golden value that is a JSON number, or one of the three special spellings the oracle writes as strings.
fn number(value: &Value) -> f64 {
    match value {
        Value::Number(n) => n.as_f64().expect("golden number fits f64"),
        Value::String(s) => match s.as_str() {
            "NaN" => f64::NAN,
            "Infinity" => f64::INFINITY,
            "-Infinity" => f64::NEG_INFINITY,
            other => panic!("golden: '{other}' is not a number spelling"),
        },
        other => panic!("golden: expected a number, got {other}"),
    }
}

/// The registry profile named by a golden id.
fn registry(id: &str) -> BenchmarkProfile {
    profiles::find(id)
        .unwrap_or_else(|| panic!("golden names unknown profile '{id}'"))
        .clone()
}

fn loading_mode(name: &str) -> LoadingMode {
    match name {
        "Fast" => LoadingMode::Fast,
        "Preview" => LoadingMode::Preview,
        "Original" => LoadingMode::Original,
        other => panic!("golden: unknown loading mode '{other}'"),
    }
}

fn workload(name: &str) -> BenchmarkWorkload {
    BenchmarkWorkload::from_name(name).unwrap_or_else(|| panic!("golden: unknown workload '{name}'"))
}

fn status(name: &str) -> BenchmarkResultStatus {
    BenchmarkResultStatus::from_name(name).unwrap_or_else(|| panic!("golden: unknown status '{name}'"))
}

fn problem(name: &str) -> BenchmarkProfileProblem {
    match name {
        "MissingIdOrMode" => BenchmarkProfileProblem::MissingIdOrMode,
        "InvalidSettings" => BenchmarkProfileProblem::InvalidSettings,
        "NotImplemented" => BenchmarkProfileProblem::NotImplemented,
        other => panic!("golden: unknown profile problem '{other}'"),
    }
}

/// The `error` object of a `describe` or `row` case.
fn row_error(value: &Value) -> RowError {
    match str_of(value, "kind") {
        "profile" => RowError::Profile(BenchmarkProfileError::new(
            problem(str_of(value, "problem")),
            str_of(value, "profileId"),
            str_of(value, "message"),
        )),
        "other" => RowError::Other(str_of(value, "message").to_owned()),
        other => panic!("golden: unknown error kind '{other}'"),
    }
}

/// Records one mismatch as `case: what: got X, expected Y`.
fn check(failures: &mut Vec<String>, case: &str, what: &str, actual: &str, expected: &str) {
    if actual != expected {
        failures.push(format!("{case}: {what}: got {actual:?}, expected {expected:?}"));
    }
}

/// Runs one golden case and records its mismatches.
fn run_case(case: &Value, en: &Localizer, failures: &mut Vec<String>) {
    let name = str_of(case, "name");
    let kind = str_of(case, "kind");
    let expected = &case["expected"];

    match kind {
        "profile-key" => {
            let actual = profile_key(str_of(case, "id"), str_of(case, "field"));
            check(failures, name, "profile_key", &actual, str_of_value(expected));
        }
        "profile-texts" => {
            let mut profile = registry(str_of(case, "baseId"));
            if let Some(id) = case.get("id").and_then(Value::as_str) {
                profile.id = id.to_owned();
            }
            if let Some(display) = case.get("profileName").and_then(Value::as_str) {
                profile.name = display.to_owned();
            }
            if let Some(description) = case.get("description").and_then(Value::as_str) {
                profile.description = description.to_owned();
            }
            check(
                failures,
                name,
                "name",
                &profile_name(&profile, en),
                str_of(expected, "name"),
            );
            check(
                failures,
                name,
                "description",
                &profile_description(&profile, en),
                str_of(expected, "description"),
            );
            let item = BenchmarkProfileItem::new(profile.clone());
            check(failures, name, "itemName", &item.name(en), str_of(expected, "itemName"));
            check(
                failures,
                name,
                "itemDescription",
                &item.description(en),
                str_of(expected, "itemDescription"),
            );
        }
        "progress" => {
            let actual = progress_message(str_of(case, "message"), en);
            check(failures, name, "progress_message", &actual, str_of_value(expected));
        }
        "loading-mode" => {
            let actual = loading_mode_text(loading_mode(str_of(case, "mode")), en);
            check(failures, name, "loading_mode_text", &actual, str_of_value(expected));
        }
        "workload" => {
            let actual = workload_text(workload(str_of(case, "workload")), en);
            check(failures, name, "workload_text", &actual, str_of_value(expected));
        }
        "describe" => {
            let actual = describe_error(&row_error(&case["error"]), en);
            check(failures, name, "describe_error", &actual, str_of_value(expected));
        }
        "row" => {
            let profile_id = str_of(case, "profileId");
            let profile = registry(profile_id);
            let phase_json = &case["phase"];
            let samples: Vec<f64> = phase_json["samples"]
                .as_array()
                .unwrap_or_else(|| panic!("{name}: samples is not an array"))
                .iter()
                .map(number)
                .collect();
            let message = phase_json["message"].as_str().map(str::to_owned);
            let images_per_sample = phase_json["imagesPerSample"]
                .as_i64()
                .map(|n| i32::try_from(n).unwrap_or_else(|_| panic!("{name}: imagesPerSample out of range")));
            let phase = BenchmarkPhaseResult::new(
                profile_id,
                workload(str_of(phase_json, "workload")),
                samples,
                status(str_of(phase_json, "status")),
                message,
                images_per_sample,
            );
            let error = case.get("error").filter(|v| !v.is_null()).map(row_error);
            let mut row = BenchmarkResultRow::new(profile, phase, error);
            row.is_best = case["isBest"]
                .as_bool()
                .unwrap_or_else(|| panic!("{name}: isBest is not a bool"));

            let cells = row.cell_texts(en);
            let expected_cells: Vec<&str> = expected["cells"]
                .as_array()
                .unwrap_or_else(|| panic!("{name}: expected.cells is not an array"))
                .iter()
                .map(|v| v.as_str().unwrap_or_else(|| panic!("{name}: non-string cell")))
                .collect();
            if cells.len() != expected_cells.len() {
                failures.push(format!(
                    "{name}: cell count: got {}, expected {}",
                    cells.len(),
                    expected_cells.len()
                ));
            }
            for (index, (actual, want)) in cells.iter().zip(expected_cells.iter()).enumerate() {
                check(failures, name, &format!("cell {index}"), actual, want);
            }
            check(
                failures,
                name,
                "status_text",
                &row.status_text(en),
                str_of(expected, "statusText"),
            );
        }
        "milliseconds" => {
            let count = i32::try_from(i64_of(case, "count")).unwrap_or_else(|_| panic!("{name}: count out of range"));
            let actual = milliseconds_text(number(&case["value"]), count, en);
            check(failures, name, "milliseconds_text", &actual, str_of_value(expected));
        }
        other => panic!("{name}: unknown golden kind '{other}'"),
    }
}

/// The expected value of a case whose `expected` is a plain string.
fn str_of_value(value: &Value) -> &str {
    value
        .as_str()
        .unwrap_or_else(|| panic!("expected is not a string: {value}"))
}

#[test]
fn golden_benchmark_presentation() {
    // C#: BenchmarkRowTextTests and BenchmarkTextTests (golden twin: every kind, every case of the oracle file)
    let golden = load("benchmark-presentation");
    let en = built_in_english_localizer();
    let mut failures = Vec::new();

    for case in &golden.cases {
        run_case(case, &en, &mut failures);
    }

    assert!(
        failures.is_empty(),
        "{} of {} golden cases differ from {}:\n{}",
        failures.len(),
        golden.cases.len(),
        golden.csharp_commit,
        failures.join("\n")
    );
}
